#version 300 es
precision highp float;

uniform sampler2D u_image0;
uniform float u_float0;   // gamma

in vec2 v_texCoord;
layout(location = 0) out vec4 fragColor0;

void main() {
    vec4 src = texture(u_image0, v_texCoord);

    // pow() is undefined for negative bases, and gamma 0 divides by zero.
    float gamma = max(u_float0, 0.0001);
    vec3 color = max(src.rgb, 0.0);

    fragColor0 = vec4(pow(color, vec3(1.0 / gamma)), src.a);
}

